import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.CdvW4CUT.js";const c=JSON.parse(`{"title":"Grown-ups' settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/grown-ups.md","filePath":"guide/grown-ups.md","lastUpdated":1793092343000}`),n={name:"guide/grown-ups.md"};function r(i,t,d,h,l,p){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="grown-ups-settings" tabindex="-1">Grown-ups&#39; settings <a class="header-anchor" href="#grown-ups-settings" aria-label="Permalink to &quot;Grown-ups&#39; settings&quot;">​</a></h1><h2 id="the-admin-page" tabindex="-1">The admin page <a class="header-anchor" href="#the-admin-page" aria-label="Permalink to &quot;The admin page&quot;">​</a></h2><p><code>&lt;your site&gt;/admin</code>, behind the PIN. It has:</p><ul><li><strong>Displays:</strong> every Frog Hub that has ever checked in, with ✏️ edit (name, room, mic, volume), show the welcome, wipe (erases its storage and starts it again as a new display) and forget. Displays pick up changes on their next poll, within 5 seconds.</li><li><strong>Announcements and alarms:</strong> say something on the displays now, and see or cancel alarms and timers.</li><li><strong>Assistant:</strong> what the assistant may use (below).</li><li><strong>Memory:</strong> the assistant&#39;s memory files, and asking it to remember or forget something.</li><li><strong>📜 History:</strong> what it was asked and what it answered.</li><li><strong>Voices:</strong> the wake word recordings.</li></ul><p>There&#39;s a phone app for it too: see <a href="/developers/android">the Android apps</a>.</p><h2 id="what-the-assistant-may-use" tabindex="-1">What the assistant may use <a class="header-anchor" href="#what-the-assistant-may-use" aria-label="Permalink to &quot;What the assistant may use&quot;">​</a></h2><p>Each switch applies to both brains:</p><table tabindex="0"><thead><tr><th>Switch</th><th>What it allows</th></tr></thead><tbody><tr><td>Look things up online</td><td>Web search, Wikipedia and Wikidata</td></tr><tr><td>Remember things between conversations</td><td>Its memory</td></tr><tr><td>Check the weather</td><td>The weather</td></tr><tr><td>Set alarms and timers</td><td>Alarms and timers</td></tr><tr><td>See and control the room&#39;s devices</td><td>Lights, switches, fans and speakers in the display&#39;s room</td></tr><tr><td>Play music</td><td>Music on the room&#39;s speakers, and audio links on the displays</td></tr><tr><td>Know who it&#39;s talking to</td><td>The name of whoever the display is for</td></tr><tr><td>Show cards and pictures on the screen</td><td>Cards, pictures and recipes on screen</td></tr><tr><td>Pass messages on to the other Frog Hubs</td><td>Messages, announcements and scheduled jobs</td></tr><tr><td>Keep a log of questions and answers</td><td>The History tab (off by default)</td></tr><tr><td>Find recipes on recipeapi.io</td><td>recipeapi.io rather than TheMealDB, when there&#39;s a key</td></tr></tbody></table><p>When something is switched off, the assistant is told, so it can say so kindly if asked.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p><strong>📜 History</strong> lists everything the assistant was asked and what it answered, newest first: questions at the displays (which one, who, and what it did or showed), the admin page&#39;s memory requests, announcements and scheduled jobs, and any that got no answer in time. It can be searched and cleared there.</p><p>It&#39;s <strong>off by default</strong>: switch it on on that tab or the Assistant tab. Switching it off keeps what&#39;s there until it&#39;s cleared (you&#39;re asked whether to clear it). While it&#39;s on, the assistant can search it too (&quot;what was that recipe yesterday?&quot;), apart from what grown-ups asked in admin mode or from the admin page.</p><p>It&#39;s kept in <code>~/.config/froghub/history.jsonl</code>, readable only by Frog Hub&#39;s user, and only the newest 1,000 are kept.</p><h2 id="admin-mode-on-a-display" tabindex="-1">Admin mode on a display <a class="header-anchor" href="#admin-mode-on-a-display" aria-label="Permalink to &quot;Admin mode on a display&quot;">​</a></h2><p>Typing the PIN on a display (⚙️) unlocks admin mode there for a while, checked on the server, so nobody gets it by saying they&#39;re a grown-up. In admin mode the assistant may also say what it remembers and change or delete memories (otherwise it only adds new ones), save <strong>house rules</strong> (&quot;bedtime is 8pm on school nights&quot;, &quot;no scary stories&quot;) and follow them afterwards even if a child asks otherwise, and talk plainly about how the display works.</p>',15)])])}const g=e(n,[["render",r]]);export{c as __pageData,g as default};
